from typing import List
from collections import deque

class RideSharingSystem:
    def __init__(self):
        # Two FIFO queues (arrival order) plus the set of riders still waiting.
        self.riders = deque()
        self.drivers = deque()
        self.waiting_riders = set()

    def addRider(self, riderId: int) -> None:
        self.riders.append(riderId)
        self.waiting_riders.add(riderId)

    def addDriver(self, driverId: int) -> None:
        self.drivers.append(driverId)

    def matchDriverWithRider(self) -> List[int]:
        # Lazy deletion: drop cancelled riders only when they reach the front.
        while self.riders and self.riders[0] not in self.waiting_riders:
            self.riders.popleft()

        # Emptiness check comes AFTER the drain, or a cancelled head counts as a rider.
        if self.drivers and self.riders:
            driver = self.drivers.popleft()
            rider = self.riders.popleft()
            self.waiting_riders.remove(rider)   # matched riders can no longer cancel
            return [driver, rider]
        return [-1, -1]

    def cancelRider(self, riderId: int) -> None:
        # Only a rider that exists and is still waiting can be cancelled; the queue is untouched.
        if riderId in self.waiting_riders:
            self.waiting_riders.remove(riderId)

