import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;

class RideSharingSystem {
    // Two FIFO queues (arrival order) plus the set of riders still waiting.
    private final Queue<Integer> riders;
    private final Queue<Integer> drivers;
    private final Set<Integer> activeRiders;

    public RideSharingSystem() {
        riders = new ArrayDeque<>();
        drivers = new ArrayDeque<>();
        activeRiders = new HashSet<>();
    }

    public void addRider(int riderId) {
        riders.offer(riderId);
        activeRiders.add(riderId);
    }

    public void addDriver(int driverId) {
        drivers.offer(driverId);
    }

    public int[] matchDriverWithRider() {
        // Lazy deletion: drop cancelled riders only when they reach the front.
        while (!riders.isEmpty() && !activeRiders.contains(riders.peek())) {
            riders.poll();
        }

        // Emptiness check comes AFTER the drain.
        if (riders.isEmpty() || drivers.isEmpty()) {
            return new int[] {-1, -1};
        }

        int riderId = riders.poll();
        int driverId = drivers.poll();
        activeRiders.remove(riderId);   // matched riders can no longer cancel
        return new int[] {driverId, riderId};
    }

    public void cancelRider(int riderId) {
        // Removing from the set is a no-op for unknown or already-matched ids.
        activeRiders.remove(riderId);
    }
}

