#include <queue>
#include <unordered_set>
#include <vector>

using namespace std;

class RideSharingSystem {
private:
    // Two FIFO queues (arrival order) plus the set of riders still waiting.
    queue<int> drivers;
    queue<int> riders;
    unordered_set<int> activeRiders;

public:
    RideSharingSystem() {
    }

    void addRider(int riderId) {
        riders.push(riderId);
        activeRiders.insert(riderId);
    }

    void addDriver(int driverId) {
        drivers.push(driverId);
    }

    vector<int> matchDriverWithRider() {
        // Lazy deletion: drop cancelled riders only when they reach the front.
        while (!riders.empty() && activeRiders.find(riders.front()) == activeRiders.end()) {
            riders.pop();
        }

        // Emptiness check comes AFTER the drain.
        if (drivers.empty() || riders.empty()) {
            return {-1, -1};
        }

        int driverId = drivers.front();
        drivers.pop();

        int riderId = riders.front();
        riders.pop();
        activeRiders.erase(riderId);   // matched riders can no longer cancel

        return {driverId, riderId};
    }

    void cancelRider(int riderId) {
        // erase is a no-op for unknown or already-matched ids.
        activeRiders.erase(riderId);
    }
};

