type RideSharingSystem struct {
    // Two FIFO queues (arrival order) plus the set of riders still waiting.
    drivers []int
    riders  []int
    active  map[int]bool
}

func Constructor() RideSharingSystem {
    return RideSharingSystem{
        drivers: make([]int, 0),
        riders:  make([]int, 0),
        active:  make(map[int]bool),
    }
}

func (this *RideSharingSystem) AddRider(riderId int) {
    this.riders = append(this.riders, riderId)
    this.active[riderId] = true
}

func (this *RideSharingSystem) AddDriver(driverId int) {
    this.drivers = append(this.drivers, driverId)
}

func (this *RideSharingSystem) MatchDriverWithRider() []int {
    // Lazy deletion: drop cancelled riders only when they reach the front.
    for len(this.riders) > 0 {
        frontRider := this.riders[0]
        if this.active[frontRider] {
            break
        }
        this.riders = this.riders[1:]
    }

    // Emptiness check comes AFTER the drain.
    if len(this.drivers) == 0 || len(this.riders) == 0 {
        return []int{-1, -1}
    }

    driver := this.drivers[0]
    rider := this.riders[0]

    this.drivers = this.drivers[1:]
    this.riders = this.riders[1:]
    delete(this.active, rider)   // matched riders can no longer cancel

    return []int{driver, rider}
}

func (this *RideSharingSystem) CancelRider(riderId int) {
    // Only a rider that is still waiting can be cancelled; the queue is untouched.
    if this.active[riderId] {
        delete(this.active, riderId)
    }
}
